import{_ as a,o as d,c as o,a5 as t}from"./chunks/framework.-jms6n7v.js";const f=JSON.parse('{"title":"Dart 변경 기록","description":"Dart 패키지 darudb와 darudbgenerator의 변경 기록이며, 최신 기록이 위에 옵니다. 패키지마다 버전을 따로 매기고 기록도 따로 둡니다. 다른 언어 패키지의 기록은 사이드바에서 언어를 바꾸면 볼 수 있습니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로,…","frontmatter":{"title":"Dart 변경 기록","order":1,"editLink":false,"outline":[2,3],"prev":{"text":"MapCollection","link":"/ko/types/dart/map-collection"},"next":{"text":"다른 DB와 비교","link":"/ko/compare"}},"headers":[{"level":2,"title":"Dart 패키지 darudb","slug":"dart-패키지-darudb","link":"#dart-패키지-darudb","children":[{"level":3,"title":"darudb vNext (2026--)","slug":"darudb-vnext-2026","link":"#darudb-vnext-2026","children":[{"level":4,"title":"Added","slug":"added","link":"#added","children":[]},{"level":4,"title":"Changed","slug":"changed","link":"#changed","children":[]}]},{"level":3,"title":"darudb v1.4.0 (2026-10-29)","slug":"darudb-v1-4-0-2026-10-29","link":"#darudb-v1-4-0-2026-10-29","children":[{"level":4,"title":"Added","slug":"added-1","link":"#added-1","children":[]},{"level":4,"title":"Changed","slug":"changed-1","link":"#changed-1","children":[]},{"level":4,"title":"Fixed","slug":"fixed","link":"#fixed","children":[]}]},{"level":3,"title":"darudb v1.3.0 (2026-10-13)","slug":"darudb-v1-3-0-2026-10-13","link":"#darudb-v1-3-0-2026-10-13","children":[{"level":4,"title":"Added","slug":"added-2","link":"#added-2","children":[]},{"level":4,"title":"Changed","slug":"changed-2","link":"#changed-2","children":[]}]},{"level":3,"title":"darudb v1.2.0 (2026-10-11)","slug":"darudb-v1-2-0-2026-10-11","link":"#darudb-v1-2-0-2026-10-11","children":[{"level":4,"title":"Changed","slug":"changed-3","link":"#changed-3","children":[]},{"level":4,"title":"Fixed","slug":"fixed-1","link":"#fixed-1","children":[]}]},{"level":3,"title":"darudb v1.1.0 (2026-10-09)","slug":"darudb-v1-1-0-2026-10-09","link":"#darudb-v1-1-0-2026-10-09","children":[{"level":4,"title":"Breaking changes","slug":"breaking-changes","link":"#breaking-changes","children":[]},{"level":4,"title":"Added","slug":"added-3","link":"#added-3","children":[]},{"level":4,"title":"Changed","slug":"changed-4","link":"#changed-4","children":[]},{"level":4,"title":"Fixed","slug":"fixed-2","link":"#fixed-2","children":[]}]},{"level":3,"title":"darudb v1.0.1 (2026-10-07)","slug":"darudb-v1-0-1-2026-10-07","link":"#darudb-v1-0-1-2026-10-07","children":[{"level":4,"title":"Added","slug":"added-4","link":"#added-4","children":[]}]},{"level":3,"title":"darudb v1.0.0 (2026-10-05)","slug":"darudb-v1-0-0-2026-10-05","link":"#darudb-v1-0-0-2026-10-05","children":[{"level":4,"title":"Added","slug":"added-5","link":"#added-5","children":[]}]}]},{"level":2,"title":"Dart 패키지 darudb_generator","slug":"dart-패키지-darudb-generator","link":"#dart-패키지-darudb-generator","children":[{"level":3,"title":"darudb_generator vNext (2026--)","slug":"darudb-generator-vnext-2026","link":"#darudb-generator-vnext-2026","children":[{"level":4,"title":"Added","slug":"added-6","link":"#added-6","children":[]}]},{"level":3,"title":"darudb_generator v1.1.0 (2026-10-09)","slug":"darudb-generator-v1-1-0-2026-10-09","link":"#darudb-generator-v1-1-0-2026-10-09","children":[{"level":4,"title":"Added","slug":"added-7","link":"#added-7","children":[]},{"level":4,"title":"Changed","slug":"changed-5","link":"#changed-5","children":[]}]},{"level":3,"title":"darudb_generator v1.0.0 (2026-10-05)","slug":"darudb-generator-v1-0-0-2026-10-05","link":"#darudb-generator-v1-0-0-2026-10-05","children":[{"level":4,"title":"Added","slug":"added-8","link":"#added-8","children":[]}]}]}],"relativePath":"ko/changelog/dart.md","filePath":"ko/changelog/dart.md","lastUpdated":null}'),i={name:"ko/changelog/dart.md"};function n(s,e,r,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="dart-변경-기록" tabindex="-1">Dart 변경 기록 <a class="header-anchor" href="#dart-변경-기록" aria-label="Permalink to &quot;Dart 변경 기록&quot;">​</a></h1><p>Dart 패키지 <code>darudb</code>와 <code>darudb_generator</code>의 변경 기록이며, 최신 기록이 위에 옵니다. 패키지마다 버전을 따로 매기고 기록도 따로 둡니다. 다른 언어 패키지의 기록은 사이드바에서 언어를 바꾸면 볼 수 있습니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로, 아래 항목은 원문 그대로입니다.</p><h2 id="dart-패키지-darudb" tabindex="-1">Dart 패키지 <code>darudb</code> <a class="header-anchor" href="#dart-패키지-darudb" aria-label="Permalink to &quot;Dart 패키지 `darudb`&quot;">​</a></h2><h3 id="darudb-vnext-2026" tabindex="-1">darudb vNext (2026--) <a class="header-anchor" href="#darudb-vnext-2026" aria-label="Permalink to &quot;darudb vNext (2026--)&quot;">​</a></h3><h4 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>Cascading links: <code>@Cascade()</code> on a <code>Link</code> field, nullable or not, makes deleting the object the link names delete the object that holds the link, and so on down the chain, cycles included, in the same transaction, through <code>delete</code>, <code>deleteWhere</code>, their <code>Future</code> forms and a migration&#39;s function. <code>delete</code> still returns whether the object it was given was there, and <code>deleteWhere</code> how many objects its query found. Only a link to one object of the collection itself cascades. An index on the field is how a delete finds the objects to take with it: without one, each delete reads the whole collection that links. <code>FieldSpec.cascade</code> declares it and reads it back from <code>Database.storedSchema</code>. A file with a cascading link is in object format 2, which earlier releases do not open.</li><li>Indexes on several fields, and on fields inside embedded objects: <code>@IndexOn([&#39;last&#39;, &#39;first&#39;], unique: true)</code> beside <code>@Collection()</code> on the class, as many as it needs, each on 1 to 8 fields by their Dart names or paths such as <code>&#39;home.city&#39;</code>. <code>CollectionSchema.indexes</code> holds them as <code>IndexSpec</code>s by the names the collection stores, and a collection read as maps reads them back. A query testing the first fields for equality and the next for a range reads one range of entries, and one that sorts by the fields after them gets its objects in order. A unique one refuses two objects with the same values in every field, though any number may hold null in one. Such an index needs object format 2.</li><li>Lists of embedded objects: a <code>List</code> of an <code>@Embedded()</code> class is a field, written with <code>FieldSink.objectList</code> and read with <code>FieldSource.objectList</code>, and <code>EmbeddedListField</code> reaches the elements&#39; fields in a query, <code>q.stops.city.equals(&#39;Busan&#39;)</code>, where a condition holds when it holds for any element, and sets the list whole with <code>set</code>. A collection read as maps reads one as a list of maps. Such a list has no index and no sort, and its default is the empty list. It needs object format 2, as a date does.</li><li><code>DateTime</code> fields: a date, kept to the microsecond, written in UTC whatever the time&#39;s zone and read back as a <code>DateTime</code> in UTC. <code>DateKind</code> declares one, <code>DateField</code> tests one in the typed query builder with <code>equals</code>, <code>lessThan</code>, <code>between</code> and the rest, and <code>MapQuery.dateField(name)</code> in a collection read as maps, a list of them is a <code>List&lt;DateTime&gt;</code>, <code>min</code> and <code>max</code> give one, and a condition, a parameter or <code>DATE &quot;2026-10-30T12:00:00Z&quot;</code> in the query language compares it with a <code>DateTime</code>. The first date a schema declares moves the file to object format 2, which releases of the package before this one do not open; <code>upgradeFormat: false</code> refuses that with <code>INVALID_ARGUMENT</code>. A date beyond what a <code>DateTime</code> holds fails with <code>INVALID_ARGUMENT</code> when it is read.</li><li><code>QueryBuilder.linkedFrom(schema, (q) =&gt; q.link, [where])</code> holds for an object that some object of <code>schema</code>&#39;s collection links to through the link field the function picks, and that meets <code>where</code>, a condition on that collection&#39;s typed fields: <code>q.linkedFrom(postSchema, (p) =&gt; p.author, (p) =&gt; p.year.atLeast(2020))</code>. <code>~</code> of it finds the objects nothing links to. It is <code>ANY posts.author (year &gt;= 2020)</code> in the query language.</li><li>Tests that ignore case: <code>ignoreCase: true</code> on the <code>equals</code>, <code>notEquals</code>, <code>isIn</code>, <code>contains</code>, <code>startsWith</code> and <code>endsWith</code> of a <code>StringField</code>, and on the <code>contains</code>, <code>containsAny</code>, <code>anyStartsWith</code> and <code>anyEndsWith</code> of a <code>StringListField</code>, and <code>Condition.ignoreCase()</code> for every such test inside a condition, compare strings by Unicode&#39;s simple case folding, as <code>IGNORE CASE</code> does in the query language: <code>q.where(q.name.equals(&#39;kim&#39;, ignoreCase: true))</code>. A test that orders, or one of a field holding no strings, fails with <code>INVALID_QUERY</code>. The package ships <code>LICENSE-UNICODE</code>, the licence notice of the Unicode data the folding comes from.</li><li><code>deleteWhere</code> and <code>updateWhere</code> on a write collection, and on one of the <code>Future</code> API, delete or update every object a query finds, after its sort, offset and limit, and return how many there were: <code>users.updateWhere((q) =&gt; [q.active.set(false)], (q) =&gt; q.where(q.age.lessThan(18)))</code>. The query is required; <code>(q) =&gt; q</code> finds every object. <code>deleteWhereText</code>, <code>updateWhereText</code> and the <code>Prepared</code> forms take the query as text or prepared. An update by query is all or nothing: when one object is refused, by a unique value taken or an index entry too long, the objects changed before it are put back. It cannot set the primary key.</li><li>Aggregates: <code>sum</code>, <code>min</code>, <code>max</code> and <code>avg</code> on a collection, and on one of the <code>Future</code> API, work out one value from a field of the objects a query finds, after its sort, offset and limit: <code>users.sum((q) =&gt; q.age, (q) =&gt; q.where(q.age.atLeast(18)))</code>. The field is picked from the query builder, so it may be a field of an embedded object or of a linked object, and the result has its type: <code>sum</code> of an <code>IntField</code> is an <code>int</code>, of a <code>FloatField</code> a <code>double</code>, and <code>min</code> and <code>max</code> are of the field&#39;s type or <code>null</code>. <code>avg</code> is a <code>double</code> or <code>null</code>. Nulls are left out, and a sum of no values is 0. <code>sumText</code>, <code>sumPrepared</code> and the like take the query in the query language or prepared.</li></ul><h4 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>The native library is built with its functions aligned to 64 bytes as well as its loops, so that where a hot function lands no longer depends on the rest of the build: in the engine&#39;s benchmark on an Apple M1 Max, a count through an index had run 12% slower after changes that left its code as it was, and it no longer does. It is about 3% larger for it.</li></ul><h3 id="darudb-v1-4-0-2026-10-29" tabindex="-1">darudb v1.4.0 (2026-10-29) <a class="header-anchor" href="#darudb-v1-4-0-2026-10-29" aria-label="Permalink to &quot;darudb v1.4.0 (2026-10-29)&quot;">​</a></h3><h4 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>plain</code> in <code>Database.backup</code> and <code>Database.backupAsync</code>, which writes the copy with no encryption: the way to turn an encrypted database into a plain one, which put in the encrypted file&#39;s place opens without a key or a password. Auto-increment counters and the stored schema come across as they are. <code>plain</code> beside a <code>key</code> or a <code>password</code> fails with <code>INVALID_ARGUMENT</code>.</li></ul><h4 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>A query sorted by an indexed field, with an offset and nothing of its filter left to test on the objects it reads, skips the objects before its page by their keys, rather than reading each of them. A page of 50 objects after up to 98,703 others took 0.69 ms rather than 19 ms on an Apple M1 Max.</li><li>A query whose filter has terms that indexes answer alone gathers the keys of the objects that meet them from the indexes, and combines them before it reads an object, when counting the indexes&#39; entries says that is cheaper: terms joined by <code>AND</code> meet, terms joined by <code>OR</code> join, a test through a link field with an index, such as <code>author.country == &quot;kr&quot;</code>, goes through the linked collection&#39;s index and then the link&#39;s, and a query sorted by an indexed field with a limit walks that index and takes only the gathered keys. In the benchmark&#39;s complex suite on an Apple M1 Max, a count with <code>OR</code> across two indexes took 92% less time, a count with conditions on two indexes 69% less, three conditions on two indexes sorted with a limit 39% less, the first 20 posts of authors in one country 93% less, a count through two links 93% less, and the first 20 posts with a tag sorted by another index 95% less.</li><li>A set of gathered keys that are all ints lying close together, as an auto-increment collection&#39;s keys are, is looked up through a bit for each int rather than a table of their hashes, and its keys are read once to find their order and their range. In the benchmark&#39;s complex suite on an Apple M1 Max, against the sets of keys above, the count with conditions on two indexes took 40% less time, the count through two links 33% less, the count with <code>OR</code> 27% less, three conditions sorted with a limit 19% less, the first 20 posts of authors in one country 17% less, and the first 20 posts with a tag 7% less.</li><li><code>CONTAINS</code> on a string searches the string&#39;s bytes with a searcher made once for the query, and checks the string is UTF-8 only where it finds the text, rather than checking and searching each string anew. A query that counts the posts whose text contains two words in a row, over 300,000 posts with no index, took 11% less time on an Apple M1 Max. The engine depends on the <code>memchr</code> crate, MIT OR Unlicense, for the search.</li><li><code>update</code> of fields that hold scalars changes the record where it lies in a collection with lists, embedded objects or links too, copying their values as they are, rather than reading the object and writing it whole again.</li></ul><h4 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li>A synchronous call whose result is small, made after one whose result passed 1 MiB, such as <code>check</code> after an <code>insertMany</code> of a hundred thousand objects, read its result from memory the library had already freed. On iOS the app crashed; elsewhere the result could be wrong.</li></ul><h3 id="darudb-v1-3-0-2026-10-13" tabindex="-1">darudb v1.3.0 (2026-10-13) <a class="header-anchor" href="#darudb-v1-3-0-2026-10-13" aria-label="Permalink to &quot;darudb v1.3.0 (2026-10-13)&quot;">​</a></h3><h4 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>A database opened without a schema works with the one the file holds, as it is. <code>Database.storedCollection</code> gives each of its collections as a <code>MapCollection</code>, whose objects are maps by the names the file stores, read and written with the stored schema&#39;s checks and indexes kept as ever, and queried with <code>MapQuery</code>, which names a field by its stored name and says what it holds. A float field takes an <code>int</code>, a link a primary key or a <code>Link</code>, and a name the schema lacks is refused rather than dropped. A generated schema whose fields are the stored ones reaches its collection too. Nothing is stored, checked or migrated, so a program can open a file whose schema it does not know. A file that holds no schema has no collections then, as before.</li><li><code>Database.storedSchema</code>, the schema a database works with: the declared one, or the file&#39;s own as <code>MapCollection</code>s, whose <code>FieldSpec</code>s describe each field&#39;s name, kind, whether it is optional, its default and its index, and whether it is the primary key. It is still there after the database closes.</li></ul><h4 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li><code>schemaVersion</code> gives the version of the file&#39;s own schema for a database opened without one, where it gave <code>null</code>.</li><li>Reaching a collection of a database without a schema fails with the engine&#39;s error, as in every other language: <code>INVALID_ARGUMENT</code> when the file holds no schema, or stored one after the database opened, and <code>CORRUPTED</code> or <code>UNSUPPORTED_FORMAT_VERSION</code> when the one it holds does not read.</li></ul><h3 id="darudb-v1-2-0-2026-10-11" tabindex="-1">darudb v1.2.0 (2026-10-11) <a class="header-anchor" href="#darudb-v1-2-0-2026-10-11" aria-label="Permalink to &quot;darudb v1.2.0 (2026-10-11)&quot;">​</a></h3><h4 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>A sync commit on Linux, Android and the BSDs makes the file durable with <code>fdatasync</code> rather than <code>fsync</code>, which leaves out the file&#39;s times and still syncs its length with its data. A sync commit of one object takes a quarter less time for it on a GitHub-hosted Linux runner, 312 µs against 413. macOS, iOS and Windows sync as before.</li><li>A commit asks the file system for the file&#39;s length only when its record counts pages past both the published commit&#39;s and the last one the commit wrote, rather than at every commit. A deferred commit of one object takes 11% less time for it on a GitHub-hosted Linux runner, 22.3 µs against 25.1.</li><li>A query that reads every object, as one that tests or sorts by a field without an index does, remembers where that field lies in each record it read, beside the page cache, and the next query that tests or sorts by the same field reads it there. On a GitHub-hosted Linux runner, a query of one value of such a field took a fifth less time the next time it ran, and one of the ten objects with the highest value of such a field a quarter less. A filter that is one test of one field is also made without going through the filter&#39;s tree, and compares a short string in place, which takes another tenth off such a query each time it runs. The first run takes a few percent more, and what is remembered takes up to a sixteenth more memory than the page cache&#39;s size.</li><li>An equality in a filter that is one test of one field is tested in place, rather than through a call for every object, which takes 6% off a query of one value of a field without an index in the engine.</li><li>A read transaction keeps the root of each collection and index it looks a key up in, and a key it looks up is encoded on the stack when it is a number or a short string. A lookup by primary key or by a unique field takes 8 to 9% less time for it on a GitHub-hosted Linux runner.</li></ul><h4 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>MigrationContext.previous</code> reads a list of links as the keys they hold, as it reads one link, where it gave the package&#39;s internal link objects.</li><li><code>findText</code>, <code>countText</code>, <code>findPrepared</code> and <code>countPrepared</code> of an asynchronous collection complete their <code>Future</code> with the error when they fail, as every other call of the <code>Future</code> API does. A text that does not parse, or a prepared query of another collection, threw before the <code>Future</code> was returned.</li><li><code>Database.open</code>, <code>openAsync</code>, <code>backup</code>, <code>backupAsync</code>, <code>salvage</code> and <code>salvageAsync</code> wipe every copy of the key or password they make on the way to the engine. The buffer the options were written into, which could be left behind when it grew, and the password&#39;s UTF-8 bytes stayed in memory until the garbage collector reclaimed them.</li><li><code>backup</code> and <code>backupAsync</code> refuse a <code>passwordHashing</code> cost out of range with <code>INVALID_ARGUMENT</code> before they write anything, as opening does, whether a password is given or not. With a password they failed with <code>INTERNAL</code>, and without one they ignored the cost.</li></ul><h3 id="darudb-v1-1-0-2026-10-09" tabindex="-1">darudb v1.1.0 (2026-10-09) <a class="header-anchor" href="#darudb-v1-1-0-2026-10-09" aria-label="Permalink to &quot;darudb v1.1.0 (2026-10-09)&quot;">​</a></h3><h4 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h4><ul><li>The file format is version 6, the top-level <code>formatVersion</code>, which earlier releases cannot open. Opening a file of version 5 raises it to version 6 while no other process has it open, so a file this release has opened no longer opens with 1.0, in Dart or in any other language&#39;s package. An app that may go back to an earlier release, or that shares its file with a program still on one, such as an app extension, opens with <code>upgradeFormat: false</code>, which also creates new files in version 5, and calls <code>upgradeFormat</code> once nothing older opens the file.</li></ul><h4 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>The <code>upgradeFormat</code> parameter of <code>Database.open</code> and <code>openAsync</code>, and <code>upgradeFormat</code> and <code>upgradeFormatAsync</code>, which say whether opening raises a file of an older format version, and raise an open one.</li></ul><h4 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>An index whose entries for one value come in key order, as a non-unique index&#39;s do while the objects&#39; primary keys grow, fills its pages as it goes, where splitting a page in the middle left half of each empty, and so do the branches of every tree. A file of 400,000 sample objects with 14 indexes is 7% smaller for it. Keys in no particular order split pages evenly, as before.</li><li><code>compact</code> and <code>compactAsync</code> first write again, full, every tree whose pages inserts left part empty, so that the file ends about as small as a backup&#39;s copy: the same file compacts to 119 MiB rather than 140 MiB.</li><li>File format 6 writes the lengths in a leaf&#39;s entries as varints rather than in five bytes. A file of 400,000 sample objects with 14 indexes takes 8% fewer pages, 126 MiB against 138, and compacts to 110 MiB against 119, with reads and writes as fast as before. A file raised from version 5 has only its header rewritten; its leaves take the new layout as writes change them, and <code>compact</code> rewrites the trees where that saves room.</li><li>The native library is built with its loops aligned to 64 bytes, so that where a hot loop lands no longer depends on the rest of the build: in a development build, the position of one loop alone made one-object deferred commits 15% slower. It is about 7% larger for it. The build for 64-bit Arm Windows is the exception, since the compiler cannot write that platform&#39;s unwind information for a function with padding inside it.</li></ul><h4 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>compact</code> and <code>compactAsync</code> no longer grow the file when a value in an overflow run near the file&#39;s end finds no run of free pages below to move into. The run stays where it is, and a round of moves that would grow the file is dropped.</li><li>The README and the guide name Flutter 3.38.1 as the oldest release the package installs on, where they said 3.38. Flutter 3.38.0 ships a build of Dart 3.10.0 numbered <code>3.10.0-290.4.beta</code>, which the package&#39;s <code>sdk: ^3.10.0</code> has never accepted.</li><li>The package resolves in a Flutter app on Flutter 3.38.1 to 3.44, the oldest releases it supports. It asked for versions of <code>hooks</code>, <code>code_assets</code> and <code>native_toolchain_rust</code> that need <code>meta</code> 1.19, which those Flutter releases pin lower, so <code>flutter pub get</code> failed there.</li></ul><h3 id="darudb-v1-0-1-2026-10-07" tabindex="-1">darudb v1.0.1 (2026-10-07) <a class="header-anchor" href="#darudb-v1-0-1-2026-10-07" aria-label="Permalink to &quot;darudb v1.0.1 (2026-10-07)&quot;">​</a></h3><h4 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>An example, <code>example/main.dart</code>, which stores a few objects, finds them by an index in code and as text, changes one, and opens the file again. pub.dev shows it on the package&#39;s Example tab.</li></ul><h3 id="darudb-v1-0-0-2026-10-05" tabindex="-1">darudb v1.0.0 (2026-10-05) <a class="header-anchor" href="#darudb-v1-0-0-2026-10-05" aria-label="Permalink to &quot;darudb v1.0.0 (2026-10-05)&quot;">​</a></h3><h4 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database.open</code> opens or creates a database file, with a <code>Schema</code> of the collections <code>darudb_generator</code> generates from classes annotated <code>@Collection()</code> and <code>@Embedded()</code>, and the options <code>create</code>, <code>pageSize</code>, <code>busyTimeout</code>, <code>cacheSize</code>, <code>key</code>, <code>password</code> and <code>passwordHashing</code>; a <code>key</code> and a <code>password</code> together are refused with <code>INVALID_ARGUMENT</code>, here and in <code>salvage</code> and <code>backup</code>. A file holding an older schema version is migrated in one write transaction, through the <code>Migration</code>s registered for the versions in between, whose functions read the old objects through <code>MigrationContext</code>.</li><li><code>Database.read</code> and <code>Database.write</code> run a function in a transaction; <code>write</code> commits when it returns, deferred with <code>Durability.deferred</code>, and aborts when it throws. <code>txn.collection(userSchema)</code> gives a collection&#39;s objects as the annotated class: <code>get</code>, <code>find</code>, <code>findOne</code> and <code>count</code> with a typed query builder whose conditions combine with <code>&amp;</code>, <code>|</code> and <code>~</code>, <code>findText</code> for the query language, <code>Database.prepare</code> and <code>findPrepared</code>, and in a write <code>insert</code>, <code>insertMany</code>, <code>put</code>, <code>putMany</code>, <code>update</code> and <code>delete</code>. <code>update</code> takes a change for each field it sets, made by the field&#39;s <code>set</code>, an embedded object&#39;s included, which it replaces whole.</li><li><code>Database.sync</code>, <code>Database.close</code>, <code>setKey</code>, <code>setPassword</code>, <code>isEncrypted</code>, <code>pageSize</code>, <code>formatVersion</code> and <code>schemaVersion</code>. Every failure is a <code>DaruException</code> with the engine&#39;s error code.</li><li>The <code>Future</code> API: <code>Database.openAsync</code>, <code>readAsync</code>, <code>writeAsync</code>, <code>syncAsync</code>, <code>closeAsync</code>, <code>setKeyAsync</code> and <code>setPasswordAsync</code>, whose transactions give collections of <code>Future</code>-returning calls. The engine&#39;s work runs on threads of the native library, and the result comes back on the isolate&#39;s event loop. The calls of one transaction run in the order they were made; an isolate&#39;s asynchronous writes on one file take turns, and a synchronous <code>write</code>, <code>sync</code> or <code>close</code> on the file while one runs is refused with <code>INVALID_ARGUMENT</code>.</li><li>The tools, each with an <code>Async</code> twin: <code>check</code>, the integrity check, which reports every problem in a <code>CheckReport</code>; <code>backup</code>, a copy of the published commit in a new file, under a new data key when it is given a <code>key</code> or a <code>password</code> for the copy; <code>compact</code>, which makes the file smaller in place; and <code>Database.salvage</code>, which rescues what it can of a damaged file into a new one, with a key or a password for an encrypted file.</li><li>The build hook downloads the native library for the application&#39;s target from the package&#39;s GitHub release, and uses it only when its SHA-256 hash is the one <code>hook/prebuilt.json</code> names, so building an application needs no Rust toolchain. A download is kept in the hook&#39;s cache. In a checkout of the repository, which an application gets by depending on the package through git or a path, the hook builds the engine from source with <code>native_toolchain_rust</code> instead.</li></ul><h2 id="dart-패키지-darudb-generator" tabindex="-1">Dart 패키지 <code>darudb_generator</code> <a class="header-anchor" href="#dart-패키지-darudb-generator" aria-label="Permalink to &quot;Dart 패키지 `darudb_generator`&quot;">​</a></h2><h3 id="darudb-generator-vnext-2026" tabindex="-1">darudb_generator vNext (2026--) <a class="header-anchor" href="#darudb-generator-vnext-2026" aria-label="Permalink to &quot;darudb_generator vNext (2026--)&quot;">​</a></h3><h4 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>@Cascade()</code> on a <code>Link</code> field writes <code>cascade: true</code> in its <code>FieldSpec</code>. The generator refuses it on any other type, a <code>List</code> of links included, and inside an embedded class.</li><li><code>@IndexOn</code> on a collection&#39;s class declares an index on several fields or on a field inside an embedded class: the generator turns each path of Dart names into the names the collection stores and writes the <code>indexes</code> of the schema constant, and refuses a path the class does not have. It needs <code>darudb</code> with <code>IndexOn</code>, the version released with this one.</li><li>A <code>List</code> of an <code>@Embedded()</code> class is a list of embedded objects: the generator declares it with <code>ListKind(ObjectKind(...))</code>, writes and reads it with <code>FieldSink.objectList</code> and <code>FieldSource.objectList</code>, and gives the query builder the <code>ListFields</code> class it now writes beside the <code>Fields</code> of every embedded class, such as <code>StopListFields</code>.</li><li>A <code>DateTime</code> field, or a <code>List&lt;DateTime&gt;</code>, is a date: the generator declares it with <code>DateKind</code>, writes and reads it with <code>FieldSink.date</code> and <code>FieldSource.date</code>, and gives the query builder a <code>DateField</code> for it. It needs <code>darudb</code> with date support, the version released with this one. A <code>DateTime</code> has no constant, so a date field has no default.</li></ul><h3 id="darudb-generator-v1-1-0-2026-10-09" tabindex="-1">darudb_generator v1.1.0 (2026-10-09) <a class="header-anchor" href="#darudb-generator-v1-1-0-2026-10-09" aria-label="Permalink to &quot;darudb_generator v1.1.0 (2026-10-09)&quot;">​</a></h3><h4 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>An example, <code>example/README.md</code>, of a class the generator reads and the code an application writes with what it generates.</li></ul><h4 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>Versioned 1.1.0 together with <code>darudb</code> 1.1.0. The code it generates is the same as 1.0.0&#39;s, and works with <code>darudb</code> 1.0 and 1.1 alike.</li></ul><h3 id="darudb-generator-v1-0-0-2026-10-05" tabindex="-1">darudb_generator v1.0.0 (2026-10-05) <a class="header-anchor" href="#darudb-generator-v1-0-0-2026-10-05" aria-label="Permalink to &quot;darudb_generator v1.0.0 (2026-10-05)&quot;">​</a></h3><h4 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>The builder <code>darudb</code>, which writes for each class annotated <code>@Collection()</code> its schema constant, record codec, query builder, link type and <code>copyWith</code>, and for each class annotated <code>@Embedded()</code> its schema constant, codec, query fields and <code>copyWith</code>, into the library&#39;s <code>.g.dart</code> part. It refuses a class it cannot store with an error that names the field: a field that is not final, a type the database does not store, a nullable field with a default, two primary keys, a collection without a key and without <code>int? id</code>, or an index inside an embedded object.</li><li>Runs on Dart 3.10 and later, with <code>analyzer</code> from 12.1 and <code>source_gen</code> from 4.2.4, the newest of each that resolves on Dart 3.10.</li></ul>',52)])])}const b=a(i,[["render",n]]);export{f as __pageData,b as default};
